<?php
declare(strict_types=1);
namespace Hostider\OfflineBackup;
use Hostider\Core\{Config,CanonicalJson};
use Hostider\Core\Database\Database;
final class Guard
{
 public const MAX_ARCHIVE=100_663_296,MAX_PLAIN=67_108_864,MAX_FRAME=262_144,MAX_ROWS=20_000,MAX_DB=16_777_216,MAX_FILES=512,MAX_FILE_BYTES=33_554_432,RESERVE=134_217_728;
 public static function require(bool $ok,string $code):void{if(!$ok){throw new \RuntimeException('F6F_'.$code);}}
 public static function gate():void{self::require(PHP_SAPI==='cli'&&PHP_VERSION_ID>=80300&&PHP_INT_SIZE===8&&getenv('APP_ENV')==='test'&&getenv('F6F_SYNTHETIC_ALLOWED')==='1','TEST_ONLY');self::require(extension_loaded('pdo_mysql')&&extension_loaded('sodium')&&function_exists('posix_geteuid')&&function_exists('fsync')&&posix_geteuid()!==0,'CAPABILITIES_NONROOT');}
 public static function id(string $s):string{self::require(preg_match('/\A[a-f0-9]{24}\z/D',$s)===1,'OPERATION_ID');return $s;}
 public static function name(string $s):string{self::require(preg_match('/\A[a-z][a-z0-9_]{0,63}\z/D',$s)===1,'IDENTIFIER');return '`'.$s.'`';}
 public static function fields(array $v,array $fields):void{$a=array_keys($v);sort($a);sort($fields);self::require($a===$fields,'FIELDS');}
 public static function hash(mixed $v):string{return hash('sha256',CanonicalJson::encode($v));}
 public static function directory(string $p,int $mode=0700):void{clearstatcache(true,$p);$s=lstat($p);self::require($s!==false&&($s['mode']&0170000)===0040000&&($s['mode']&0777)===$mode&&$s['uid']===posix_geteuid()&&realpath($p)===$p,'DIRECTORY');$q=$p;while($q!=='/'){self::require(!is_link($q),'PATH_LINK');$q=dirname($q);}}
 public static function mkdir(string $p):void{self::require(!file_exists($p)&&!is_link($p)&&mkdir($p,0700),'MKDIR');self::directory($p);}
 public static function file(string $p,int $mode=0600):array{clearstatcache(true,$p);$s=lstat($p);self::require($s!==false&&($s['mode']&0170000)===0100000&&($s['mode']&0777)===$mode&&$s['uid']===posix_geteuid()&&$s['nlink']===1,'FILE');return $s;}
 public static function open(string $p,string $mode='rb',int $permissions=0600):mixed{if($mode==='x+b'){self::require(!file_exists($p)&&!is_link($p),'NO_OVERWRITE');}else{$before=self::file($p,$permissions);}$f=@fopen($p,$mode);self::require(is_resource($f),'OPEN');try{if($mode==='x+b'){self::require(chmod($p,$permissions),'PERMISSION');}$s=fstat($f);$n=self::file($p,$permissions);self::require($s!==false&&$s['ino']===$n['ino']&&$s['dev']===$n['dev']&&(!isset($before)||($before['ino']===$s['ino']&&$before['dev']===$s['dev'])),'FILE_RACE');return $f;}catch(\Throwable $e){fclose($f);throw $e;}}
 public static function write(mixed $f,string $b):void{$o=0;while($o<strlen($b)){$n=fwrite($f,substr($b,$o));self::require(is_int($n)&&$n>0,'WRITE');$o+=$n;}}
 public static function syncDir(string $p,int $mode=0700):void{self::directory($p,$mode);$h=@fopen($p,'r');self::require(is_resource($h),'DIRECTORY_FD');try{self::require(fsync($h),'DIRECTORY_SYNC');}finally{fclose($h);}}
 public static function save(string $p,array $v):void{$b=CanonicalJson::encode($v);$tmp=$p.'.next';if(file_exists($tmp)){self::file($tmp);self::require(unlink($tmp),'JOURNAL_CLEAN');}$f=self::open($tmp,'x+b');try{self::write($f,$b);self::require(fflush($f)&&fsync($f),'SYNC');}finally{fclose($f);}if(file_exists($p)){self::file($p);}self::require(rename($tmp,$p),'JOURNAL_RENAME');self::syncDir(dirname($p));}
 public static function space(string $p):void{$n=disk_free_space($p);self::require($n!==false&&$n>=self::RESERVE,'DISK_SPACE');}
 public static function database(Database $db,array $kinds=['source','target','reference']):void{self::gate();$schema=(string)$db->execute('SELECT DATABASE()')->fetchColumn();self::require(preg_match('/\Af6f_(src|dst|ref)_([a-f0-9]{24})\z/D',$schema,$m)===1,'NATIVE_DB_SCOPE');$kind=match($m[1]){'src'=>'source','dst'=>'target','ref'=>'reference'};self::require(in_array($kind,$kinds,true),'NATIVE_DB_KIND');$v=$db->execute('SELECT operation_id,kind,token_hash FROM f6f_control WHERE id=1')->fetch();self::require($v&&$v['kind']===$kind&&preg_match('/\A[a-f0-9]{24}\z/D',$v['operation_id'])===1&&preg_match('/\A[a-f0-9]{64}\z/D',$v['token_hash'])===1&&($kind!=='source'||$m[2]===$v['operation_id']),'NATIVE_DB_MARKER');}
 public static function databaseSpace(Database $db):void{$dir=rtrim((string)$db->execute('SELECT @@datadir')->fetchColumn(),'/');$rows=$db->execute('SELECT PATH AS mount_path,AVAILABLE AS free_kib FROM information_schema.DISKS')->fetchAll();$best=null;foreach($rows as $v){$path=rtrim($v['mount_path'],'/');if(($path===''||$dir===$path||str_starts_with($dir,$path.'/'))&&($best===null||strlen($path)>strlen($best['path']))){Guard::require(is_numeric($v['free_kib'])&&preg_match('/\A[0-9]{1,18}\z/D',(string)$v['free_kib'])===1,'DB_DISK_METADATA');$best=['path'=>$path,'available'=>(int)$v['free_kib']];}}self::require($best!==null&&$best['available']>=intdiv(self::RESERVE,1024),'DB_DISK_SPACE');}
 public static function connect(#[\SensitiveParameter] array $c,string $schema):Database{self::require(preg_match('/\A(?:hostider_f0_test|f6f_(?:src|dst|ref)_[a-f0-9]{24})\z/D',$schema)===1,'SCHEMA_SCOPE');$db=Database::connect(new Config('test','https://offline.example.invalid',$c['app_key'],'mysql:host=127.0.0.1;port='.$c['port'].';dbname='.$schema.';charset=utf8mb4',$c['account'],$c['password']));$db->execute('SET SESSION lock_wait_timeout=2');$db->execute('SET SESSION innodb_lock_wait_timeout=2');$db->execute('SET SESSION max_statement_time=2');return $db;}
 public static function config(#[\SensitiveParameter] array $c):Database{self::gate();self::fields($c,['classification','port','account','password','app_key','instance_token']);self::require($c['classification']==='SYNTHETIC'&&is_int($c['port'])&&$c['port']>0&&$c['port']<=65535&&is_string($c['account'])&&preg_match('/\A[a-zA-Z0-9_]{1,64}\z/D',$c['account'])===1&&is_string($c['password'])&&strlen($c['password'])<=256&&is_string($c['app_key'])&&strlen((string)base64_decode($c['app_key'],true))===32&&is_string($c['instance_token'])&&preg_match('/\A[a-f0-9]{64}\z/D',$c['instance_token'])===1,'CONFIG');$db=self::connect($c,'hostider_f0_test');$v=$db->execute('SELECT token_hash,expires_at>UTC_TIMESTAMP(6) fresh,expires_at<=TIMESTAMPADD(SECOND,3600,UTC_TIMESTAMP(6)) bounded FROM f6f_test_instance WHERE id=1')->fetch();self::require($v&&(int)$v['fresh']===1&&(int)$v['bounded']===1&&hash_equals($v['token_hash'],hash('sha256',$c['instance_token'])),'DEDICATED_INSTANCE');self::require(str_contains((string)$db->execute('SELECT VERSION()')->fetchColumn(),'MariaDB'),'MARIADB');return $db;}
}
